    version BIGINT NOT NULL DEFAULT 0,
    deleted_at TIMESTAMPTZ,
    deleted_by BIGINT,
    CONSTRAINT ck_messaging_email_account_provider CHECK (provider IN ('smtp', 'enterprise_mail', 'aliyun', 'tencent', 'tencent_mail', 'mail_139', 'gmail', 'microsoft', 'sendgrid', 'mailgun', 'amazon_ses', 'postmark', 'resend'))
